<?php
namespace Nakhostin\PerformanceEngine\Assets;
final class AssetDecision { public const KEEP = 'keep'; public const DEFER = 'defer'; public const UNLOAD = 'unload'; public const UNKNOWN = 'unknown'; private $handle; private $decision; private $reason; private $confidence; public function __construct( string $handle, string $decision, string $reason, int $confidence = 0 ) { $this->handle = sanitize_key( $handle ); $this->decision = in_array( $decision, array( self::KEEP, self::DEFER, self::UNLOAD, self::UNKNOWN ), true ) ? $decision : self::UNKNOWN; $this->reason = sanitize_text_field( $reason ); $this->confidence = max( 0, min( 100, $confidence ) ); } public function to_array(): array { return array( 'handle' => $this->handle, 'decision' => $this->decision, 'reason' => $this->reason, 'confidence' => $this->confidence ); } }
